Here's your expense tracker. Add an expense, pick a month, and it totals each category as you go. Your entries stay in this page only if your device allows saving, so don't count on them lasting.

```page
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f7f4;color:#1f2a24}
  h2{margin:0 0 12px;font-size:20px}
  .card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select{padding:8px;border:1px solid #cdd5cf;border-radius:8px;font-size:14px;flex:1;min-width:110px}
  button{padding:8px 14px;border:0;border-radius:8px;background:#2f7d57;color:#fff;font-size:14px;cursor:pointer}
  button.x{background:#fff;color:#a33;padding:2px 8px;font-size:16px}
  .big{font-size:28px;font-weight:600}
  .muted{color:#6a756e;font-size:13px}
  .bar{height:10px;background:#e4eae6;border-radius:6px;overflow:hidden;margin:3px 0 9px}
  .bar div{height:100%;background:#2f7d57}
  .over{color:#b3261e}
  .item{display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px solid #eef1ee}
  .item:last-child{border-bottom:0}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <input id="month" type="month" value="2026-11">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹)">
  </div>
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="muted" id="left"></div>
</div>

<div class="card">
  <div class="row">
    <input id="desc" placeholder="What was it?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <input id="date" type="date" value="2026-11-12">
    <button id="add">Add</button>
  </div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">By category</div>
  <div id="cats"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">Entries</div>
  <div id="list"></div>
</div>

<script>
var items = [];
var budget = 0;
try {
  items = JSON.parse(localStorage.getItem('foo_exp') || '[]');
  budget = Number(localStorage.getItem('foo_budget') || 0);
} catch (e) {}
var $ = function (id) { return document.getElementById(id); };
function inr(n) { return '₹' + Math.round(n).toLocaleString('en-IN'); }
function save() {
  try {
    localStorage.setItem('foo_exp', JSON.stringify(items));
    localStorage.setItem('foo_budget', String(budget));
  } catch (e) {}
}
function render() {
  var m = $('month').value;
  var rows = items.filter(function (i) { return i.date.slice(0, 7) === m; })
    .sort(function (a, b) { return a.date < b.date ? 1 : -1; });
  var total = rows.reduce(function (s, i) { return s + i.amt; }, 0);
  $('total').textContent = inr(total);
  var left = $('left');
  left.className = 'muted';
  if (budget > 0) {
    var diff = budget - total;
    if (diff >= 0) { left.textContent = inr(diff) + ' left of ' + inr(budget); }
    else { left.textContent = inr(-diff) + ' over your budget of ' + inr(budget); left.className = 'muted over'; }
  } else { left.textContent = 'Set a budget to see what is left.'; }

  var byCat = {};
  rows.forEach(function (i) { byCat[i.cat] = (byCat[i.cat] || 0) + i.amt; });
  var cats = $('cats'); cats.innerHTML = '';
  var keys = Object.keys(byCat).sort(function (a, b) { return byCat[b] - byCat[a]; });
  if (!keys.length) { cats.textContent = 'Nothing yet.'; cats.className = 'muted'; }
  keys.forEach(function (k) {
    var wrap = document.createElement('div');
    var t = document.createElement('div');
    t.textContent = k + ': ' + inr(byCat[k]);
    var bar = document.createElement('div'); bar.className = 'bar';
    var fill = document.createElement('div');
    fill.style.width = (total ? byCat[k] / total * 100 : 0) + '%';
    bar.appendChild(fill); wrap.appendChild(t); wrap.appendChild(bar); cats.appendChild(wrap);
  });

  var list = $('list'); list.innerHTML = '';
  if (!rows.length) { list.textContent = 'No entries for this month.'; list.className = 'muted'; }
  else list.className = '';
  rows.forEach(function (i) {
    var d = document.createElement('div'); d.className = 'item';
    var l = document.createElement('div');
    l.textContent = (i.desc || i.cat) + ' · ' + i.cat + ' · ' + i.date;
    var r = document.createElement('div');
    var a = document.createElement('span'); a.textContent = inr(i.amt) + ' ';
    var x = document.createElement('button'); x.className = 'x'; x.textContent = '×';
    x.onclick = function () { items = items.filter(function (z) { return z.id !== i.id; }); save(); render(); };
    r.appendChild(a); r.appendChild(x); d.appendChild(l); d.appendChild(r); list.appendChild(d);
  });
}
$('add').onclick = function () {
  var amt = Number($('amt').value);
  if (!(amt > 0) || !$('date').value) return;
  items.push({ id: Date.now() + Math.random(), desc: $('desc').value.trim(), amt: amt, cat: $('cat').value, date: $('date').value });
  $('desc').value = ''; $('amt').value = '';
  $('month').value = $('date').value.slice(0, 7);
  save(); render();
};
$('budget').value = budget || '';
$('budget').oninput = function () { budget = Number($('budget').value) || 0; save(); render(); };
$('month').onchange = render;
render();
</script>
</body>
</html>
```
